<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
final class Design_Core_Elementor_Semantic_Tokenizer {
 private const STOP=array('elementor'=>true,'widget'=>true,'control'=>true,'controls'=>true,'general'=>true,'basic'=>true,'pro'=>true,'core'=>true,'design'=>true,'default'=>true,'style'=>true,'settings'=>true);
 public static function tokens($value,$drop_stop=false){$parts=array();self::collect($value,$parts);$tokens=array();foreach($parts as $part){$part=preg_replace('/([a-z0-9])([A-Z])/u','$1 $2',(string)$part);$part=preg_replace('/([A-Z]+)([A-Z][a-z])/u','$1 $2',$part);$part=str_replace(array('\\','/','_','-','.',':','|','+','&'),' ',$part);$part=self::lower(preg_replace('/[^\p{L}\p{N}]+/u',' ',$part));foreach(preg_split('/\s+/u',trim($part))?:array() as $token){if(''===$token)continue;if($drop_stop&&isset(self::STOP[$token]))continue;$tokens[$token]=true;}}return array_keys($tokens);}
 public static function phrase_tokens($phrase){return self::tokens((string)$phrase,true);}public static function has_all(array $tokens,$phrase){$need=self::phrase_tokens($phrase);if(!$need)return false;foreach($need as $n){if(!in_array($n,$tokens,true))return false;}return true;}public static function overlap(array $tokens,array $terms){$wanted=self::tokens($terms,true);if(!$wanted)return 0.0;$have=array_flip($tokens);$m=0;foreach($wanted as $t){if(isset($have[$t]))$m++;}return $m/count($wanted);}private static function collect($value,array &$out){if(is_scalar($value)){$out[]=(string)$value;return;}if(!is_array($value))return;foreach($value as $item)self::collect($item,$out);}private static function lower($value){return function_exists('mb_strtolower')?mb_strtolower((string)$value):strtolower((string)$value);}
}
